// Characterization tests: pin CURRENT behaviour of order totals, quirks included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 0.99, D: 33.33, E: 101, F: 100 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (items) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ items }),
})
const totalFor = async (items) => {
  const res = await post(items)
  assert.equal(res.status, 201)
  return (await res.json()).total
}

test('sums unit price * qty across lines', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 3 }]), 95)
})

test('no discount at or below 100 (threshold is strictly > 100)', async () => {
  assert.equal(await totalFor([{ sku: 'F', qty: 1 }]), 100)
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100)
})

test('10% discount applies once total exceeds 100', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 11 }]), 99)   // 110 -> 99
  assert.equal(await totalFor([{ sku: 'E', qty: 1 }]), 90)    // 101 -> 90.9 -> 90
})

test('discount is flat 10% for large orders (no tiers)', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 100 }]), 900)
  assert.equal(await totalFor([{ sku: 'B', qty: 1000 }]), 22500)
})

test('total is floored (truncated), not rounded, to whole euros', async () => {
  assert.equal(await totalFor([{ sku: 'C', qty: 1 }]), 0)      // 0.99 -> 0
  assert.equal(await totalFor([{ sku: 'D', qty: 1 }]), 33)     // 33.33 -> 33
  assert.equal(await totalFor([{ sku: 'D', qty: 4 }]), 119)    // 133.32*0.9=119.988 -> 119
})

test('a discounted order can total less than an undiscounted one just under the threshold', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100)
  assert.equal(await totalFor([{ sku: 'A', qty: 11 }]), 99)
})

test('total is stored and returned by GET /orders/:id', async () => {
  const created = await (await post([{ sku: 'A', qty: 11 }])).json()
  const fetched = await (await fetch(`${base}/orders/${created.id}`)).json()
  assert.deepEqual(fetched, created)
  assert.equal(fetched.total, 99)
})

test('invalid bodies are rejected with 400', async () => {
  for (const items of [[], undefined, 'x']) {
    const res = await post(items)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('unknown order returns 200 with an error body (quirk); unknown route is 404', async () => {
  const res = await fetch(`${base}/orders/nope`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
  assert.equal((await fetch(`${base}/other`)).status, 404)
})
EOF
